{
	"name": "pl_erp_erp",
	"properties": {
		"description": "Copies one table from erp to landing.",
		"activities": [
			{
				"name": "copy_invoices",
				"description": "Copies erp.dbo.Invoices to landing as Parquet.",
				"type": "Copy",
				"inputs": [
					{
						"referenceName": "ds_erp_erp_erp",
						"type": "DatasetReference"
					}
				],
				"outputs": [
					{
						"referenceName": "ds_erp_landing",
						"type": "DatasetReference",
						"parameters": {
							"folder": "erp/erp.dbo.Invoices",
							"file": "@{concat(formatDateTime(pipeline().parameters.windowStart, 'yyyyMMddHHmmss'), '_', pipeline().RunId, '.parquet')}"
						}
					}
				],
				"typeProperties": {
					"source": {
						"type": "SqlSource",
						"sqlReaderQuery": "SELECT\n  [invoice_id],\n  [amount],\n  [modified_at]\nFROM [dbo].[Invoices]"
					},
					"sink": {
						"type": "ParquetSink",
						"storeSettings": {
							"type": "AzureBlobFSWriteSettings"
						},
						"formatSettings": {
							"type": "ParquetWriteSettings"
						}
					}
				}
			}
		],
		"parameters": {
			"windowStart": {
				"type": "string"
			},
			"windowEnd": {
				"type": "string"
			}
		},
		"annotations": [
			"Generated by Ingestron from the erp definitions"
		]
	}
}

