{
	"name": "pl_erp_erp",
	"properties": {
		"description": "Copies one table from erp to landing.",
		"activities": [
			{
				"name": "for_each_table",
				"description": "Copies each table in the tables parameter, 4 at a time.",
				"type": "ForEach",
				"typeProperties": {
					"items": {
						"value": "@pipeline().parameters.tables",
						"type": "Expression"
					},
					"isSequential": false,
					"batchCount": 4,
					"activities": [
						{
							"name": "copy_table",
							"description": "Copies the current table to landing as Parquet.",
							"type": "Copy",
							"userProperties": [
								{
									"name": "table",
									"value": "@item().table"
								}
							],
							"inputs": [
								{
									"referenceName": "ds_erp_erp_erp",
									"type": "DatasetReference"
								}
							],
							"outputs": [
								{
									"referenceName": "ds_erp_landing",
									"type": "DatasetReference",
									"parameters": {
										"folder": {
											"value": "@item().folder",
											"type": "Expression"
										},
										"file": {
											"value": "@{if(empty(item().file), concat(formatDateTime(pipeline().parameters.windowStart, 'yyyyMMddHHmmss'), '_', pipeline().RunId, '.parquet'), item().file)}",
											"type": "Expression"
										}
									}
								}
							],
							"typeProperties": {
								"source": {
									"type": "SqlSource",
									"sqlReaderQuery": {
										"value": "@{item().query}@{if(empty(item().watermark), '', concat(' WHERE ', item().watermark, ' >= ''', formatDateTime(pipeline().parameters.windowStart, 'yyyy-MM-dd HH:mm:ss'), ''' AND ', item().watermark, ' < ''', formatDateTime(pipeline().parameters.windowEnd, 'yyyy-MM-dd HH:mm:ss'), ''''))}",
										"type": "Expression"
									}
								},
								"sink": {
									"type": "ParquetSink",
									"storeSettings": {
										"type": "AzureBlobFSWriteSettings"
									},
									"formatSettings": {
										"type": "ParquetWriteSettings"
									}
								}
							}
						}
					]
				}
			}
		],
		"parameters": {
			"windowStart": {
				"type": "string"
			},
			"windowEnd": {
				"type": "string"
			},
			"tables": {
				"type": "array",
				"defaultValue": [
					{
						"table": "invoices",
						"object": "erp.dbo.Invoices",
						"connection": "erp",
						"query": "SELECT\n  [invoice_id],\n  [amount],\n  [modified_at]\nFROM [dbo].[Invoices]",
						"watermark": "",
						"folder": "erp/erp.dbo.Invoices",
						"file": ""
					}
				]
			}
		},
		"annotations": [
			"Generated by Ingestron from the erp definitions"
		]
	}
}

