{
	"name": "pl_erp_erp",
	"properties": {
		"description": "Copies one table from erp to landing.",
		"activities": [
			{
				"name": "copy_invoices",
				"description": "Copies the files of sales/orders to landing as they are.",
				"type": "Copy",
				"inputs": [
					{
						"referenceName": "ds_erp_erp",
						"type": "DatasetReference",
						"parameters": {
							"root": "sales",
							"folder": "orders"
						}
					}
				],
				"outputs": [
					{
						"referenceName": "ds_erp_landing_files",
						"type": "DatasetReference",
						"parameters": {
							"folder": "erp/sales/orders"
						}
					}
				],
				"typeProperties": {
					"source": {
						"type": "BinarySource",
						"storeSettings": {
							"type": "AmazonS3ReadSettings",
							"recursive": true,
							"wildcardFileName": "*",
							"modifiedDatetimeStart": "@{formatDateTime(pipeline().parameters.windowStart, 'yyyy-MM-dd''T''HH:mm:ss''Z''')}",
							"modifiedDatetimeEnd": "@{formatDateTime(pipeline().parameters.windowEnd, 'yyyy-MM-dd''T''HH:mm:ss''Z''')}"
						}
					},
					"sink": {
						"type": "BinarySink",
						"storeSettings": {
							"type": "AzureBlobFSWriteSettings",
							"copyBehavior": "PreserveHierarchy"
						}
					}
				}
			}
		],
		"parameters": {
			"windowStart": {
				"type": "string"
			},
			"windowEnd": {
				"type": "string"
			}
		},
		"annotations": [
			"Generated by Ingestron from the erp definitions"
		]
	}
}

